type ApartmentRequirementsModalProps = {
  serviceId?: string;
  serviceTitle: string;
  startingPrice: string;
  duration: string;
  buttonClassName: string;
  buttonLabel?: string;
};

function ApartmentRequirementsModal({
  serviceId,
  buttonClassName,
  buttonLabel = "Add",
}: ApartmentRequirementsModalProps) {
  if (!serviceId) {
    return null;
  }

  return (
    <Link
      href={`${FULL_HOME_DETAILS_PATH}${serviceId}`}
      className={buttonClassName}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        textDecoration: "none",
      }}
    >
      {buttonLabel}
    </Link>
  );
}

type FurnishingType =
  | "furnished"
  | "unfurnished";

type HomeCleaningService = {
  id: string;
  furnishingType: FurnishingType;
  groupTitle: string;
  title: string;
  promoTitle: string;
  promoDescription: string;
  rating: number | null;
  reviews: string;
  price: string;
  originalPrice?: string;
  duration: string;
  badge?: string;
  imagePending?: boolean;
  features: readonly string[];
};

