type FullApartmentProps = {
  furnishingType?: FurnishingType;
};

export default function FullApartment({
  furnishingType = "unfurnished",
}: FullApartmentProps) {
  const visibleServices =
    homeCleaningServices.filter(
      (service) =>
        service.furnishingType ===
        furnishingType,
    );

  return (
    <section
      id="full-apartment-section"
      data-service-scroll-target
      className={"cc-fh-apartment-section"}
      aria-label={
        furnishingType === "furnished"
          ? "Furnished home cleaning services"
          : "Unfurnished home cleaning services"
      }
    >
      <style>{CITY_COOLIES_INLINE_CSS_FULLAPARTMENT}</style>
      <div className={"cc-fh-apartment-serviceList"}>
        {visibleServices.map(
          (service, index) => (
            <div
              key={service.id}
              className={"cc-fh-apartment-serviceGroup"}
            >
              <h2
                className={
                  index === 0
                    ? "cc-fh-apartment-sectionTitle"
                    : "cc-fh-apartment-subSectionTitle"
                }
              >
                {service.groupTitle}
              </h2>

              <article
                className={"cc-fh-apartment-apartmentService"}
              >
                <div
                  data-service-id={service.id}
                  className={`${"cc-fh-apartment-promoBanner"} ${
                    service.imagePending
                      ? "cc-fh-apartment-imagePending"
                      : ""
                  }`}
                >
                  {service.badge ? (
                    <span
                      className={"cc-fh-apartment-bestValue"}
                    >
                      {service.badge}
                    </span>
                  ) : null}

</div>

                <div
                  className={
                    "cc-fh-apartment-serviceDetails"
                  }
                >
                  <div
                    className={
                      "cc-fh-apartment-serviceHeader"
                    }
                  >
                    <div
                      className={
                        "cc-fh-apartment-serviceInformation"
                      }
                    >
                      <h3
                        className={`${"cc-fh-apartment-serviceTitle"} ${
                          service.id === "furnished-apartment"
                            ? "cc-fh-apartment-furnishedApartmentTitle"
                            : ""
                        }`}
                      >
                        {service.title}
                      </h3>

                      {service.rating !==
                      null ? (
                        <div
                          className={
                            "cc-fh-apartment-ratingRow"
                          }
                        >
                          <span
                            className={
                              "cc-fh-apartment-ratingIcon"
                            }
                            aria-hidden="true"
                          >
                            ★
                          </span>

                          <span>
                            {service.rating.toFixed(
                              service.id === "furnished-bungalow-duplex" ||
                          service.id === "unfurnished-bungalow-duplex" ||
                          service.id === "furnished-villa-cleaning" ||
                          service.id === "unfurnished-villa-cleaning"
                                ? 1
                                : 2,
                            )}
                          </span>

                          {service.reviews ? (
                            <span
                              className={
                                "cc-fh-apartment-reviewText"
                              }
                            >
                              (
                              {
                                service.reviews
                              }
                              )
                            </span>
                          ) : null}

                        {/* CITY_COOLIES_FURNISHED_VIEW_DETAILS_IN_RATING */}
                        {(service.id === "furnished-apartment" ||
                          service.id === "unfurnished-apartment") && (
                          <ApartmentRequirementsModal
                            serviceId={service.id}
                            serviceTitle={service.title}
                            startingPrice={service.price}
                            duration={service.duration}
                            buttonClassName={`${"cc-fh-apartment-detailsButton"} ${"cc-fh-apartment-ratingDetailsButton"}`}
                            buttonLabel="View details"
                          />
                        )}

                        {/* CITY_COOLIES_BUNGALOW_VIEW_DETAILS_IN_RATING */}
                        {(service.id === "furnished-bungalow-duplex" ||
                          service.id === "unfurnished-bungalow-duplex" ||
                          service.id === "furnished-villa-cleaning" ||
                          service.id === "unfurnished-villa-cleaning") && (
                          null
                        )}</div>
                      ) : null}

                      <div
                        className={
                          "cc-fh-apartment-priceRow"
                        }
                      >
                        {(service.id === "furnished-bungalow-duplex" ||
                          service.id === "unfurnished-bungalow-duplex" ||
                          service.id === "furnished-villa-cleaning" ||
                          service.id === "unfurnished-villa-cleaning") ? (
                          <strong>
                            Site survey charges ₹500
                          </strong>
                        ) : (
                          <>
                            <strong>
                              Starts at{" "}
                              {service.price}
                            </strong>

                            <span
                              aria-hidden="true"
                            >
                              •
                            </span>

                            <span>
                              {service.duration}
                            </span>
                          </>
                        )}
                      </div>
                    </div>

                    {(
                      service.id === "unfurnished-apartment" ||
                      service.id === "furnished-apartment"
                    ) ? (
                      <ApartmentRequirementsModal
                        serviceId={
                          service.id
                        }
                        serviceTitle={
                          service.title
                        }
                        startingPrice={
                          service.price
                        }
                        duration={
                          service.duration
                        }
                        buttonClassName={
                          "cc-fh-apartment-addButton"
                        }
                      />
                    ) : (
                      service.id === "furnished-bungalow-duplex" ||
                          service.id === "unfurnished-bungalow-duplex" ||
                          service.id === "furnished-villa-cleaning" ||
                          service.id === "unfurnished-villa-cleaning"
                    ) ? (
                      null
                    ) : (
                      <button
                        type="button"
                        className={
                          "cc-fh-apartment-addButton"
                        }
                      >
                        Add
                      </button>
                    )}
                  </div>

                  <div
                    className={"cc-fh-apartment-divider"}
                  />

                                    {service.id === "furnished-bungalow-duplex" && (
<ul
                    className={"cc-fh-apartment-features"}
                  >
                    {service.features.map(
                      (feature) => (
                        <li key={feature}>
                          {feature}
                        </li>
                      ),
                    )}
                  </ul>
                  )}
                </div>
              </article>
            </div>
          ),
        )}
      </div>
    </section>
  );
}
